const ArgParser = struct {
    exe: []const u8,
    args: []const []const u8,

    pub fn init(allocator: std.mem.Allocator) !ArgParser {
        var args = std.ArrayList([]const u8).init(allocator);
        var arg_it = std.process.argsWithAllocator(allocator) catch |err| {
            std.debug.print("failed to get args: {}\n", .{err});
            return err;
        };
        defer arg_it.deinit();

        const exe = arg_it.next().?;
        while (arg_it.next()) |arg| {
            try args.append(arg);
        }

        return ArgParser{
            .exe = exe,
            .args = args.toOwnedSlice(),
        };
    }

    pub fn deinit(self: *ArgParser, allocator: std.mem.Allocator) void {
        allocator.free(self.args);
    }

    pub fn getArg(self: *const ArgParser, name: []const u8) ?[]const u8 {
        for (self.args, 0..) |arg, i| {
            if (std.mem.eql(u8, arg, name)) {
                if (i + 1 < self.args.len) {
                    return self.args[i + 1];
                }
            }
        }
        return null;
    }

    pub fn hasArg(self: *const ArgParser, name: []const u8) bool {
        for (self.args) |arg| {
            if (std.mem.eql(u8, arg, name)) {
                return true;
            }
        }
        return false;
    }
};

fn parseIntList(allocator: std.mem.Allocator, string: []const u8) !std.ArrayList(u64) {
    var list = std.ArrayList(u64).init(allocator);
    var it = std.mem.split(u8, string, ",");
    while (it.next()) |s| {
        const val = try std.fmt.parseInt(u64, s, 10);
        try list.append(val);
    }
    return list;
}

const FpuPeBw = struct { u32, u32, f64 };

fn parseMultipleTuples(allocator: std.mem.Allocator, value: []const u8) !std.ArrayList(FpuPeBw) {
    var list = std.ArrayList(FpuPeBw).init(allocator);
    var trimmed = std.mem.trim(u8, value, "[] ");
    var it = std.mem.split(u8, trimmed, "), (");
    while (it.next()) |tuple_str_raw| {
        const tuple_str = std.mem.trim(u8, tuple_str_raw, "() ");
        var parts = std.mem.split(u8, tuple_str, ",");
        const fpu_num_str = parts.next() orelse return error.ParseError;
        const fpu_freq_str = parts.next() orelse return error.ParseError;
        const bw_str = parts.next() orelse return error.ParseError;

        const fpu_num = try std.fmt.parseInt(u32, std.mem.trim(u8, fpu_num_str, " "), 10);
        const fpu_freq = try std.fmt.parseInt(u32, std.mem.trim(u8, fpu_freq_str, " "), 10);
        const bw = try std.fmt.parseFloat(f64, std.mem.trim(u8, bw_str, " "));
        try list.append(.{ fpu_num, fpu_freq, bw });
    }
    return list;
}

