fn conductDse(allocator: std.mem.Allocator, args: Args) !void {
    var file = try std.fs.cwd().openFile(args.model_shape, .{});
    defer file.close();
    var reader = file.reader();
    const model_shape_config_str = try reader.readAllAlloc(allocator, 10 * 1024 * 1024);
    defer allocator.free(model_shape_config_str);

    var json_value = try std.json.parseFromSlice(std.json.Value, allocator, model_shape_config_str, .{});
    defer json_value.deinit();
    const model_shape_config = json_value.value.object;

    const model_shape = model_parser.ModelShape{
        .dim = @intFromFloat(model_shape_config.get("hidden_dim").?.integer),
        .ffn_dim = @intFromFloat(model_shape_config.get("intermediate_dim").?.integer),
        .n_heads = @intFromFloat(model_shape_config.get("q_head_num").?.integer),
        .n_kv_heads = @intFromFloat(model_shape_config.get("kv_head_num").?.integer),
    };

    if (std.mem.eql(u8, args.execution_type, "parse")) {
        try model_parser.parseGraph(allocator, args.model_type, model_shape, args.parser_output_dir);
        return;
    }

    const operator_graph_path = try std.fs.path.join(allocator, &.{ args.parser_output_dir, "operator_graph.json" });
    defer allocator.free(operator_graph_path);

    if (!std.fs.cwd().access(operator_graph_path, .{})) {
        try model_parser.parseGraph(allocator, args.model_type, model_shape, args.parser_output_dir);
    }

    const model_args = try dse.ModelArgs.initFromConfig(args);
    var op_graph_file = try std.fs.cwd().openFile(operator_graph_path, .{});
    defer op_graph_file.close();
    const op_graph_str = try op_graph_file.reader().readAllAlloc(allocator, 100 * 1024 * 1024);
    defer allocator.free(op_graph_str);
    var op_graph_json = try std.json.parseFromSlice(std.json.Value, allocator, op_graph_str, .{});
    defer op_graph_json.deinit();

    var model = try dse.Model.init(allocator, model_args, op_graph_json.value.object, args.precision);
    defer model.deinit(allocator);

    try std.fs.cwd().makeDirAll(args.dse_output_dir);

    const dse_params = dse.DSEParams{
        .log_dir = args.dse_output_dir,
        .process_num = args.process_num,
        .seed = args.seed,
        .population_num_per_generation = args.population_num_per_generation,
        .num_generations = args.num_generations,
        .mutate_ratio = args.mutate_ratio,
        .topk = args.topk,
    };

    var fixed_device: ?*dse.Device = null;
    if (args.is_device_fixed) {
        std.debug.assert(args.nmp_channel_num_space.len == 1);
        std.debug.assert(args.fpu_pe_bw_space.len == 1);
        std.debug.assert(args.input_buffer_size_space.len == 1);
        std.debug.assert(args.weight_buffer_size_space.len == 1);
        std.debug.assert(args.output_buffer_total_size_space.len == 1);

        const device_ptr = try allocator.create(dse.Device);
        device_ptr.* = try dse.Device.initFromHardwareDesignSpace(
            dse.DataPrecision.from_string(args.precision),
            args.total_channel_num,
            args.bank_num_per_channel,
            args.bank_memory_capacity,
            args.fpu_simd_width,
            args.nmp_channel_num_space[0],
            args.fpu_pe_bw_space[0][0],
            args.fpu_pe_bw_space[0][1],
            args.fpu_pe_bw_space[0][2],
            args.input_buffer_size_space[0],
            args.output_buffer_total_size_space[0],
            args.weight_buffer_size_space[0],
        );
        fixed_device = device_ptr;
    }

    const hardware_hyper_params = dse.HardwareHyperParams{
        .pe_precision = dse.DataPrecision.from_string(args.precision),
        .is_device_fixed = args.is_device_fixed,
        .fixed_device = fixed_device,
    };

    const hardware_design_space = dse.HardwareDesignSpace{
        .total_channel_num = args.total_channel_num,
        .bank_num_per_channel = args.bank_num_per_channel,
        .bank_max_capacity = args.bank_memory_capacity,
        .fpu_simd_width = args.fpu_simd_width,
        .nmp_channel_num_space = args.nmp_channel_num_space,
        .fpu_pe_bw_space = args.fpu_pe_bw_space,
        .input_global_buffer_size_space = args.input_buffer_size_space,
        .weight_buffer_size_space = args.weight_buffer_size_space,
        .output_global_buffer_size_space = args.output_buffer_total_size_space,
    };

    if (!std.mem.eql(u8, args.is_dataflow_fixed, "no") and !std.mem.eql(u8, args.is_dataflow_fixed, "specpim")) {
        std.debug.assert(fixed_device != null);
        var operator_shape_dict = std.StringHashMap(dse.Shape).init(allocator);
        defer operator_shape_dict.deinit();

        var node_iter = model.simplified_op_graph.nodes.iterator();
        while (node_iter.next()) |node| {
            const op_id = node.key;
            const node_data = node.value;
            const node_name = model.node_name.get(model.model_type).?.get(op_id).?;

            try operator_shape_dict.put(node_name, .{
                .B = node_data.get("B").?.integer,
                .M = node_data.get("M").?.integer,
                .N = node_data.get("N").?.integer,
                .K = node_data.get("K").?.integer,
            });
        }

        std.debug.assert(args.nmp_channel_num_space.len == 1);
        const nmp_channel_num = args.nmp_channel_num_space[0];
        const normal_channel_num = args.total_channel_num - nmp_channel_num;

        var fixed_mapping_evaluator = dse.FixedMappingEvaluator.init(
            args.is_dataflow_fixed,
            model.head_num,
            model.kv_head_num,
            nmp_channel_num,
            normal_channel_num,
            model.precision_bit_dict.get(model.precision).? / 8,
        );

        const result = try fixed_mapping_evaluator.evaluateSingleDataflow(
            allocator,
            operator_shape_dict,
            model.batch_size,
            model.input_seq_len,
            model.max_gen_len,
            model.max_seq_len,
            fixed_device.?,
        );

        const result_log_path = try std.fs.path.join(allocator, &.{ args.dse_output_dir, "result.log" });
        defer allocator.free(result_log_path);
        var log_file = try std.fs.cwd().createFile(result_log_path, .{});
        defer log_file.close();
        try log_file.writer().print("Best idv latency is {d} (per layer).\n", .{result.e2e_performance[0]});
        try log_file.writer().print("Prefill latency is {d} (per layer).\n", .{result.prefill_performance[0]});

        var decoding_sum: u64 = 0;
        for (result.decoding_performance) |val| {
            decoding_sum += val;
        }
        try log_file.writer().print("Decoding latency is {d} (per layer).\n", .{decoding_sum});

        return;
    }

    var searcher = try dse.SingleTaskSearcher.init(
        dse_params,
        hardware_hyper_params,
        hardware_design_space,
        model,
    );
    defer searcher.deinit();

    if (std.mem.eql(u8, args.is_dataflow_fixed, "specpim")) {
        dse.OPEN_SPECPIM = true;
    }
    try searcher.geneticEvolveSearchMultiProcessing(allocator);
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const args = try Args.parse(allocator);

    try conductDse(allocator, args);
}

